(S, "Which army operation launched in February 2017 is a nationwide counter-terrorism operation of the Pakistan Army?", ["Operation Zarb-e-Azb", "Operation Radd-ul-Fasaad", "Operation Rah-e-Nijat", "Operation Al-Mizan"], 1, "Operation Radd-ul-Fasaad was launched in February 2017 to eliminate the remaining threat of terrorism across the country.", "Operation Azm-e-Istehkam was announced in 2024 as a further counter-terrorism campaign.", [406, 1155]),
(S, "Against whom did the Muslims fight the Battle of Badr?", ["Jews of Khyber", "Quraysh of Makkah", "Romans", "Persians"], 1, "The Battle of Badr in 2 AH was fought between the Muslims and the Quraysh of Makkah.", "The Muslims numbered about 313 against roughly 1000 of the Quraysh.", [5389]),
(S, "What is the opposite of contiguous?", ["Adjacent", "Touching", "Separated", "Connected"], 2, "Contiguous means sharing a border or touching, so its opposite is separated or detached.", "Contiguous comes from the Latin contingere, meaning to touch.", [3866]),
(S, "What is the border between Indian Punjab and Pakistani Punjab called?", ["Durand Line", "Radcliffe Line", "McMahon Line", "Line of Control"], 1, "The boundary between India and Pakistan in Punjab was drawn by the Radcliffe Commission in 1947 and is called the Radcliffe Line.", "The Wagah border crossing near Lahore lies on this line.", [3509]),
(S, "What is 14 - 6 - 4?", ["3", "4", "5", "9"], 1, "14 - 6 = 8, and 8 - 4 = 4.", "Subtraction is carried out from left to right.", [3279]),
